{
  "name": "STX自动微孔板培养箱",
  "name_en": "STX Automated Microplate Incubator",
  "manufacturer": "Liconic",
  "description": "一种用于微孔板样品培养与暂存的自动化培养箱，支持温度、湿度、二氧化碳和氮气环境控制，并可通过左右料盒/仓位进行微孔板进出库操作，常用于细胞培养、活细胞实验和自动化生物实验流程。",
  "description_en": "An automated incubator for culturing and storing microplates, with control of temperature, humidity, carbon dioxide, and nitrogen atmosphere. It supports plate loading and unloading through left/right cassettes or storage levels, and is commonly used in cell culture, live-cell assays, and automated biological workflows.",
  "tag_hints": [
    "automated microplate incubator",
    "cell culture",
    "temperature humidity CO2 control",
    "N2 atmosphere control",
    "plate storage and retrieval",
    "robotic incubation"
  ],
  "actions": [
    {
      "action_name": "auto-resetAndActivate",
      "description": "复位并激活培养箱。",
      "description_en": "Reset and activate the incubator."
    },
    {
      "action_name": "auto-is_ready",
      "description": "检查培养箱是否就绪可用。",
      "description_en": "Check whether the incubator is ready for operation."
    },
    {
      "action_name": "auto-inputPlate",
      "description": "将微孔板送入指定的料盒和层位。",
      "description_en": "Load a microplate into the specified cassette and level."
    },
    {
      "action_name": "auto-outputPlate",
      "description": "从指定的料盒和层位取出微孔板。",
      "description_en": "Unload a microplate from the specified cassette and level."
    },
    {
      "action_name": "auto-getClimate",
      "description": "读取培养箱当前环境参数。",
      "description_en": "Get the current climate conditions inside the incubator."
    },
    {
      "action_name": "auto-getPresetClimate",
      "description": "读取培养箱预设的环境参数。",
      "description_en": "Get the preset climate conditions of the incubator."
    },
    {
      "action_name": "auto-setPresetClimate",
      "description": "设置培养箱预设的温度、湿度、二氧化碳和氮气参数。",
      "description_en": "Set the preset temperature, humidity, carbon dioxide, and nitrogen conditions of the incubator."
    }
  ]
}

